package core

import (
	"encoding/json"
	"fmt"
	"os"
	"testing"
	"time"
)

// The C fixture is generated by test-telemetry in the ASUS build container;
// this exercises the same decoder/normalizer used for authenticated reports.
func TestRouterPluginTelemetryInterop(t *testing.T) {
	path := os.Getenv("CHVR_REPORT_FIXTURE")
	if path == "" {
		t.Skip("requires the C router telemetry fixture")
	}
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	var report probeReportMessage
	if err := json.Unmarshal(raw, &report); err != nil {
		t.Fatal(err)
	}
	routes := cloneProbeRelayStatusItems(report.RelayStatus)
	if len(routes) != 8 {
		t.Fatalf("routes=%d, want 8", len(routes))
	}
	for i, route := range routes {
		expectedRoute := probeVirtualRouterRuntimeRouteID(probeVirtualRouterTopologyRule{ID: fmt.Sprintf("vrouter-test-%d", i)})
		if route.RouteID != expectedRoute {
			t.Fatalf("runtime route=%s, want %s", route.RouteID, expectedRoute)
		}
		if route.Role != "virtual_router" || route.VirtualRouter == nil || route.BridgeStatus == nil || len(route.BridgeSessions) != 3 {
			t.Fatalf("missing router runtime: %+v", route)
		}
		for _, session := range route.BridgeSessions {
			if session.RouteID != route.RouteID || session.ConnectedMS < 2500 || session.RTTMS != 12 || session.SessionID == "" {
				t.Fatalf("invalid session: %+v", session)
			}
		}
		view := mngRouteRelayStatusView{NodeID: "7", Online: true, RouteID: route.RouteID,
			NextState: route.NextState, PrevState: route.PrevState, ListenState: route.ListenState,
			BridgeStatus: route.BridgeStatus, BridgeSessions: route.BridgeSessions}
		side := buildMngVirtualRouterRouteSideStatus("7", expectedRoute,
			map[string]probeRuntimeStatus{"7": {Online: true}},
			map[string]mngRouteRelayStatusView{"7|" + route.RouteID: view})
		if side.Status != "connected" {
			t.Fatalf("controller route status=%s", side.Status)
		}
	}
	buffers := normalizeProbeVirtualRouterBufferReport(report.VirtualRouterBuffers)
	if len(buffers.Items) != 64 {
		t.Fatalf("normalized buffers=%d, want 64", len(buffers.Items))
	}
	if _, err := time.Parse(time.RFC3339Nano, buffers.CollectedAt); err != nil {
		t.Fatal(err)
	}
	for _, item := range buffers.Items {
		if item.CarrierSlot == nil || item.PeakDepth < item.Depth || item.AllocatedCapacity < item.Depth || item.PeakAllocatedCapacity < item.AllocatedCapacity || item.StatsStartedAt != buffers.StatsStartedAt {
			t.Fatalf("invalid buffer: %+v", item)
		}
	}
}
